const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function normalizeExtension(file) {
  const explicit = normalizeString(file.extension).toLowerCase().replace(/^\./, "");
  if (explicit) return explicit;

  const filename = normalizeString(file.filename);
  const parts = filename.split(".");
  if (parts.length > 1) return parts.pop().toLowerCase();

  return "";
}

function normalizeList(list) {
  return Array.isArray(list)
    ? list.map(item => normalizeString(item).toLowerCase().replace(/^\./, "")).filter(Boolean)
    : [];
}

function findRoute(extension, routeRules) {
  if (!routeRules || typeof routeRules !== "object") return null;

  for (const [category, rule] of Object.entries(routeRules)) {
    const extensions = normalizeList(rule.extensions);
    if (extensions.includes(extension)) {
      return {
        file_category: category,
        next_component: rule.next_component || null,
        next_action: rule.next_action || null,
        rule
      };
    }
  }

  return null;
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-G",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        file_route: null,
        downstream_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-G will not route file when upstream upload failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "route_file_upload") {
  return fail({
    code: "FILE_ROUTING_NOT_REQUESTED",
    message: "source.next_action is not route_file_upload.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!source.file || typeof source.file !== "object") {
  return fail({
    code: "MISSING_FILE_OBJECT",
    message: "input.file is required."
  });
}

if (!source.file.filename) {
  return fail({
    code: "MISSING_FILENAME",
    message: "input.file.filename is required."
  });
}

const file = source.file;
const extension = normalizeExtension(file);
const mimeType = normalizeString(file.mime_type).toLowerCase();
const sizeBytes = Number(file.size_bytes || 0);

if (!extension) {
  return fail({
    code: "MISSING_FILE_EXTENSION",
    message: "File extension could not be determined."
  });
}

const blockedExtensions = normalizeList(config.blocked_extensions);
const allowedExtensions = normalizeList(config.allowed_extensions);
const maxFileSizeBytes = Number(config.max_file_size_bytes || 0);

if (blockedExtensions.includes(extension)) {
  return fail({
    code: "BLOCKED_FILE_EXTENSION",
    message: "File extension is blocked.",
    details: [
      {
        filename: file.filename,
        extension,
        blocked_extensions: blockedExtensions
      }
    ]
  });
}

if (allowedExtensions.length > 0 && !allowedExtensions.includes(extension)) {
  return fail({
    code: "UNSUPPORTED_FILE_EXTENSION",
    message: "File extension is not in allowed_extensions.",
    details: [
      {
        filename: file.filename,
        extension,
        allowed_extensions: allowedExtensions
      }
    ]
  });
}

if (maxFileSizeBytes > 0 && sizeBytes > maxFileSizeBytes) {
  return fail({
    code: "FILE_TOO_LARGE",
    message: "File exceeds configured max_file_size_bytes.",
    details: [
      {
        filename: file.filename,
        size_bytes: sizeBytes,
        max_file_size_bytes: maxFileSizeBytes
      }
    ]
  });
}

const route = findRoute(extension, config.route_rules);

if (!route || !route.next_component || !route.next_action) {
  const fileRoute = {
    file_id: file.file_id || null,
    filename: file.filename,
    extension,
    mime_type: mimeType || null,
    size_bytes: sizeBytes,
    source_url: file.source_url || null,
    storage_provider: file.storage_provider || null,
    file_category: "unknown",
    route_status: "manual_review_required",
    route_reason: "No matching route rule found.",
    routed_at: nowIso()
  };

  const manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C2-G",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      file_route: fileRoute,
      source_result: source,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "file_routing_review",
      review_reason: "No matching route rule found for uploaded file.",
      reviewer_email: config.reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "ops",
      priority: "normal",
      allowed_actions: ["route_to_spreadsheet_parser", "route_to_document_processor", "reject_file", "request_new_file"],
      default_next_action: "notify_reviewer"
    }
  };

  return [
    {
      json: {
        success: true,
        component_id: "C2-G",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        file_route: fileRoute,
        downstream_handoff: null,
        manual_review_handoff: manualReviewHandoff,
        source_result: source,
        error: null,
        next_action: "manual_review"
      }
    }
  ];
}

const fileRoute = {
  file_id: file.file_id || null,
  filename: file.filename,
  extension,
  mime_type: mimeType || null,
  size_bytes: sizeBytes,
  source_url: file.source_url || null,
  storage_provider: file.storage_provider || null,
  file_category: route.file_category,
  route_status: "routed",
  route_reason: `Matched ${route.file_category} route for .${extension}.`,
  routed_at: nowIso()
};

let downstreamInput = {
  success: true,
  component_id: "C2-G",
  component_version: "v1",
  event_id: source.event_id || null,
  event_type: source.event_type || null,
  file: {
    ...file,
    extension,
    mime_type: mimeType || file.mime_type || null
  },
  file_route: fileRoute,
  metadata: {
    source_component: source.component_id || null,
    original_event_type: source.event_type || null,
    origin: source.metadata?.origin || null,
    uploaded_at: source.metadata?.uploaded_at || null,
    routed_at: fileRoute.routed_at
  },
  error: null,
  next_action: route.next_action
};

if (route.next_component === "C2-N") {
  downstreamInput.rows = source.rows || [];
  downstreamInput.metadata.filename = file.filename;
}

const downstreamHandoff = {
  next_component: route.next_component,
  input: downstreamInput,
  config: route.rule.config || {
    source_type: route.file_category,
    source_name: file.filename,
    default_next_action: route.next_action
  }
};

return [
  {
    json: {
      success: true,
      component_id: "C2-G",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      file_route: fileRoute,
      downstream_handoff: downstreamHandoff,
      manual_review_handoff: null,
      source_result: source,
      error: null,
      next_action: config.default_next_action || "route_file"
    }
  }
];
